1	/* ============================ Lái xe: vật cản thu từ cảnh đã dựng ============================
2	   Tách khỏi solids.ts vì cần module cảnh (environment/riverfront kéo core/renderer, core/materials vẽ canvas lúc import): test node
3	   chỉ import solids.ts. Gọi MỘT lần, lần đầu vào chế độ lái (sau mọi bước dọn nhà): chỉ đọc cảnh, không đụng chuỗi rand() hay thứ tự dựng.
4	   - Nhà đang hiện của khu phố (collectBuildings: level gần của THREE.LOD, bỏ instance scale 0) và nhà quanh Thuận Phước (InstancedMesh
5	     thường của site.ts, tọa độ cục bộ group cầu): khối hộp thẳng trục từ chân tới mái.
6	   - Chân đế địa danh và pano ven sông (riverfront footprints): là hình chữ nhật dọn nhà đã nới rộng 2–9 m mỗi phía và không có chiều cao,
7	     nên phần lấn ô đường bị cắt bỏ (giữ mảnh lớn nhất còn lại), cao CONFIG.drive.solids.footTop.
8	   - Chỉ giữ vật cách mép ô gần nhất ≤ CONFIG.drive.solids.near (cho thân xe và camera); xa hơn xe không bao giờ tới.
9	   Nhà lấn ô đường thì vẫn thêm (đúng là có nhà trên đường) và đếm vào drSceneStats.intrude để test trình duyệt / người làm thấy. */
10	import * as THREE from 'three';
11	import { CONFIG } from '../../config';
12	import { collectBuildings, type Rect } from '../../environment/riverfront/clearance';
13	import { getRiverfront } from '../../environment/riverfront';
14	import { drAddSolids, type DrNet, type DrPad, type DrSolid } from './net';
15	
16	export const drSceneStats = { buildings: 0, tpHouses: 0, footprints: 0, intrude: 0, skipped: 0 };
17	
18	const _m = new THREE.Matrix4(), _p = new THREE.Vector3(), _q = new THREE.Quaternion(), _s = new THREE.Vector3();
19	const drGood = (r: Rect): boolean => [r.x0, r.x1, r.z0, r.z1].every(Number.isFinite) && r.x1 > r.x0 && r.z1 > r.z0;
20	const drOverlap = (r: Rect, p: DrPad): boolean => r.x1 > p.x0 && r.x0 < p.x1 && r.z1 > p.z0 && r.z0 < p.z1;
21	/* Khoảng cách mặt bằng nhỏ nhất từ r tới ô gần nhất (0 nếu chồng) */
22	function drPadGap(pads: DrPad[], r: Rect): number {
23	  let best = Infinity;
24	  for (const p of pads) {
25	    const dx = Math.max(0, p.x0 - r.x1, r.x0 - p.x1), dz = Math.max(0, p.z0 - r.z1, r.z0 - p.z1);
26	    best = Math.min(best, Math.hypot(dx, dz));
27	  }
28	  return best;
29	}
30	/* Cắt khỏi r phần chồng lên các ô: mỗi lần chồng giữ mảnh lớn nhất trong bốn mảnh trái / phải / trước / sau; null nếu không còn gì */
31	function drTrim(pads: DrPad[], r: Rect): Rect | null {
32	  let cur: Rect = { ...r };
33	  for (const p of pads) {
34	    if (!drOverlap(cur, p)) continue;
35	    const parts: Rect[] = [
36	      { ...cur, x1: Math.min(cur.x1, p.x0) }, { ...cur, x0: Math.max(cur.x0, p.x1) },
37	      { ...cur, z1: Math.min(cur.z1, p.z0) }, { ...cur, z0: Math.max(cur.z0, p.z1) }
38	    ].filter(drGood);
39	    if (!parts.length) return null;
40	    cur = parts.reduce((a, b) => ((b.x1 - b.x0) * (b.z1 - b.z0) > (a.x1 - a.x0) * (a.z1 - a.z0) ? b : a));
41	  }
42	  return cur;
43	}
44	
45	/* Thêm nhà đang hiện + chân đế địa danh gần ô đường vào net; trả số vật cản đã thêm */
46	export function drCollectRuntime(net: DrNet, tpHouses: THREE.InstancedMesh | null): number {
47	  const C = CONFIG.drive.solids, LAND = CONFIG.landY, pads = net.pads, out: DrSolid[] = [];
48	  const st = { buildings: 0, tpHouses: 0, footprints: 0, intrude: 0, skipped: 0 };
49	  const box = (r: Rect, y0: number, y1: number): boolean => {
50	    if (!drGood(r) || !Number.isFinite(y0) || !Number.isFinite(y1) || y1 <= y0) { st.skipped++; return false; }
51	    const gap = drPadGap(pads, r);
52	    if (gap > C.near) return false;
53	    if (gap === 0 && pads.some((p) => drOverlap(r, p))) st.intrude++;
54	    out.push({ kind: 'rect', x0: r.x0, x1: r.x1, z0: r.z0, z1: r.z1, y0, y1 });
55	    return true;
56	  };
57	  for (const b of collectBuildings()) {                             // collectBuildings đã cập nhật matrixWorld của cảnh; nhà khu phố đặt chân ở landY (city.ts)
58	    if (box({ x0: b.x - b.w / 2, x1: b.x + b.w / 2, z0: b.z - b.d / 2, z1: b.z + b.d / 2 }, LAND, LAND + b.h)) st.buildings++;
59	  }
