1	/* ===== Lái xe: hình chiếc VinFast VF 3 trong cảnh (D-034) =====
2	   - drCarLoad(): import() động GLTFLoader, nạp public/car/vf3.glb một lần, nhớ đệm. Lỗi bất kỳ hoặc quá model.timeoutMs → console.warn, null; promise không bao giờ bị từ chối.
3	     Nguồn được chuẩn hóa một lần: lớp 1 (không vào phản chiếu nước), không đổ / nhận bóng; hai vật liệu đèn vá bằng onBeforeCompile (đọc shared.uNight, không PointLight);
4	     chờ drCarSetWarm (compileAsync theo cảnh chính, ≤ model.warmMs) rồi mới trả nguồn.
5	   - Đèn: lamp_head có emissive map của nguồn, nhân hệ số theo uNight. lamp_tail không có: phát sáng = màu cơ bản (cả logo trong ảnh dán) nhân hệ số.
6	     Đèn phanh = bản vật liệu thứ hai cùng program (cùng customProgramCacheKey, chỉ khác uniform uBrake): đổi tham chiếu vật liệu của lưới đèn hậu, không biên dịch lại.
7	   - DrCar: group có ngay với hình tạm (một Mesh gộp hộp bo + bốn trụ bánh, màu theo slot) và tấm bóng mờ dưới gầm; nạp xong thì đổi sang bản sao `body` của mô hình
8	     (5 primitive = 5 lệnh vẽ, vật liệu `paint` nhân bản riêng để đặt màu slot). Bốn bánh KHÔNG thuộc group của xe: nằm trong drWheels, mỗi vật liệu của lưới bánh một
9	     InstancedMesh dùng chung cho mọi xe (3 lệnh vẽ tổng cộng), mỗi xe giữ 4 chỗ liên tiếp. drWheels.group phải nằm trong cảnh (drCars.group chứa sẵn).
10	     Lệnh vẽ: hình tạm 2 / xe; mô hình thật 5 thân + 1 bóng = 6 / xe, cộng 3 lệnh bánh chung.
11	   - Quy ước hướng: yaw 0 = mũi +X; steer > 0 rẽ trái (cùng chiều yaw); wheel = góc lăn bánh trái (rad, tăng khi xe tiến). Mô hình: mũi +X, Y lên, đáy lốp y = 0, gốc giữa hai trục.
12	     Bánh phải dùng chung lưới với bánh trái nên nút xoay 180 độ quanh Y: dấu quay quanh Z cục bộ lấy theo hướng Z cục bộ của bánh trong thế giới.
13	   Không cấp phát mỗi khung. docs/superpowers/specs/2026-11-12-lai-xe-oto-design.md */
14	import * as THREE from 'three';
15	import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
16	import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js';
17	import { CONFIG } from '../../config';
18	import { shared } from '../../core/shared';
19	import { multiParams } from '../multi/params';
20	
21	const M = CONFIG.drive.model, CAR = CONFIG.drive.car;
22	const WHEELS = ['wheel_fl', 'wheel_fr', 'wheel_rl', 'wheel_rr'];   // hai bánh đầu là bánh trước
23	const CAP = (multiParams.slots + 1) * 4;                           // chỗ bánh: 6 xe × 4
24	
25	export interface DrPlace { x: number; y: number; z: number; yaw: number; pitch: number; steer: number; wheel: number; braking: boolean }
26	
27	/* ===== Vật liệu đèn: vá phát sáng theo uNight, hệ số `night`; uBrake > phát sáng nền thì thay bằng uBrake ===== */
28	function drLampPatch(m: THREE.MeshStandardMaterial, key: string, night: number, brake: number): void {
29	  const ub = { value: brake };
30	  m.onBeforeCompile = (s) => {
31	    s.uniforms.uNight = shared.uNight;
32	    s.uniforms.uBrake = ub;
33	    s.fragmentShader = 'uniform float uNight;\nuniform float uBrake;\n' + s.fragmentShader.replace('#include <emissivemap_fragment>',
34	      `#include <emissivemap_fragment>\ntotalEmissiveRadiance *= max( clamp( uNight, 0.0, 1.0 ) * ${night.toFixed(3)}, uBrake );`);
35	  };
36	  m.customProgramCacheKey = () => key;
37	  m.userData.lampBrake = brake;
38	}
39	
40	export interface DrSource {
41	  scene: THREE.Object3D;                       // cảnh gốc (không thêm vào cảnh; chỉ để sao chép)
42	  body: THREE.Object3D;                        // nút body
43	  paint: THREE.MeshStandardMaterial;           // vật liệu sơn gốc (mỗi xe nhân bản)
44	  tail: THREE.Material; tailBrake: THREE.Material;
45	  wheels: { pos: THREE.Vector3; quat: THREE.Quaternion; sign: number }[];   // vị trí, xoay nghỉ, dấu quay quanh Z cục bộ (4 bánh theo WHEELS)
46	  wheelMeshes: THREE.Mesh[];                   // các lưới của wheel_fl (mỗi vật liệu một lưới)
47	}
48	
49	/* Chuẩn hóa cảnh đã nạp thành nguồn dùng chung. Thiếu nút / vật liệu thì ném lỗi (drCarLoad bắt, trả null) */
50	export function drCarSource(scene: THREE.Object3D): DrSource {
51	  scene.updateMatrixWorld(true);
52	  const body = scene.getObjectByName('body');
53	  if (!body) throw new Error('thiếu nút body');
54	  let paint: THREE.MeshStandardMaterial | null = null, head: THREE.MeshStandardMaterial | null = null, tail: THREE.MeshStandardMaterial | null = null;
55	  scene.traverse((o) => {
56	    o.layers.set(1);
57	    const me = o as THREE.Mesh;
58	    if (!me.isMesh) return;
59	    me.castShadow = false; me.receiveShadow = false;
60	    const mat = me.material as THREE.MeshStandardMaterial;
61	    if (mat.name === 'paint') paint = mat;
62	    else if (mat.name === 'lamp_head') head = mat;
63	    else if (mat.name === 'lamp_tail') tail = mat;
64	  });
65	  if (!paint || !head || !tail) throw new Error('thiếu vật liệu paint / lamp_head / lamp_tail');
66	  const h = head as THREE.MeshStandardMaterial, t = tail as THREE.MeshStandardMaterial;
67	  drLampPatch(h, 'drLampHead', M.headNight, 0);
68	  t.emissive.set(0xffffff); t.emissiveMap = t.map; t.emissiveIntensity = 1;   // không emissive map: lấy chính ảnh màu cơ bản
69	  drLampPatch(t, 'drLampTail', M.tailNight, 0);
70	  const tb = t.clone(); drLampPatch(tb, 'drLampTail', M.tailNight, M.tailBrake);   // cùng khóa program: chỉ khác uniform
71	  const wheels: DrSource['wheels'] = [], z = new THREE.Vector3();
72	  for (const n of WHEELS) {
73	    const w = scene.getObjectByName(n);
74	    if (!w) throw new Error(`thiếu nút ${n}`);
75	    z.set(0, 0, 1).applyQuaternion(w.quaternion);
76	    wheels.push({ pos: w.position.clone(), quat: w.quaternion.clone(), sign: z.z > 0 ? -1 : 1 });   // bánh tiến: quanh +Z thế giới góc âm
77	  }
78	  const wheelMeshes: THREE.Mesh[] = [];
79	  scene.getObjectByName(WHEELS[0]).traverse((o) => { if ((o as THREE.Mesh).isMesh) wheelMeshes.push(o as THREE.Mesh); });
80	  if (!wheelMeshes.length) throw new Error('bánh không có lưới');
81	  return { scene, body, paint: paint as THREE.MeshStandardMaterial, tail: t, tailBrake: tb, wheels, wheelMeshes };
82	}
83	
84	/* ===== Nạp (nhớ đệm) ===== */
85	let warm: ((o: THREE.Object3D) => Promise<unknown>) | null = null;
86	export function drCarSetWarm(fn: ((o: THREE.Object3D) => Promise<unknown>) | null): void { warm = fn; }
87	async function drCarWarm(o: THREE.Object3D): Promise<void> {
88	  if (!warm) return;
89	  let timer = 0;
90	  try { await Promise.race([warm(o), new Promise<void>((r) => { timer = setTimeout(r, M.warmMs) as unknown as number; })]); }
91	  catch { /* biên dịch trước lỗi: lần vẽ đầu tự biên dịch */ }
92	  finally { clearTimeout(timer); }
93	}
94	
95	async function drCarDefaultLoader(): Promise<THREE.Object3D> {
96	  const { GLTFLoader } = await import('three/addons/loaders/GLTFLoader.js');
97	  const gltf = await new GLTFLoader().loadAsync(import.meta.env.BASE_URL + M.url);
98	  return gltf.scene;
99	}
100	
101	let loader: () => Promise<THREE.Object3D> = drCarDefaultLoader;
102	let cache: Promise<THREE.Object3D | null> | null = null;
103	let sources = new WeakMap<THREE.Object3D, DrSource>();
104	let gen = 0;
105	
106	/* Nạp mô hình xe. Không bao giờ ném / từ chối: lỗi hoặc quá model.timeoutMs → warn một lần, null */
107	export function drCarLoad(): Promise<THREE.Object3D | null> {
108	  if (cache) return cache;
109	  const work = (async () => {
110	    const scene = await loader();
111	    const src = drCarSource(scene);
112	    sources.set(scene, src);
113	    await drCarWarm(scene);
114	    return scene as THREE.Object3D | null;
115	  })();
116	  let timer = 0;
117	  const p = Promise.race([work, new Promise<null>((r) => { timer = setTimeout(() => r(null), M.timeoutMs) as unknown as number; })])
118	    .catch((e) => { console.warn('Lái xe: không nạp được mô hình xe, dùng hình tạm', e); return null; })
119	    .finally(() => clearTimeout(timer));
120	  work.catch(() => { /* lỗi đã xử lý ở nhánh race; chặn cảnh báo promise bị bỏ */ });
121	  cache = p;
122	  return p;
123	}
124	
125	/* Cho test: thay bộ nạp (null: mặc định), xóa đệm, bỏ bánh dùng chung */
126	export function drCarSetLoader(fn: (() => Promise<THREE.Object3D>) | null): void {
127	  loader = fn || drCarDefaultLoader; cache = null; sources = new WeakMap(); gen++;
128	  drWheels.reset();
129	}
130	
131	/* ===== Bánh dùng chung: mỗi vật liệu một InstancedMesh, CAP chỗ ===== */
132	const A = new THREE.Matrix4(), B = new THREE.Matrix4(), Q = new THREE.Quaternion(), Q2 = new THREE.Quaternion(), UNIT = new THREE.Vector3(1, 1, 1), ZERO = new THREE.Matrix4().makeScale(0, 0, 0);
133	const AXY = new THREE.Vector3(0, 1, 0), AXZ = new THREE.Vector3(0, 0, 1);
134	
135	class DrWheelPool {
136	  readonly group = new THREE.Group();
137	  meshes: THREE.InstancedMesh[] = [];
138	  private src: DrSource | null = null;
139	  private used: boolean[] = new Array(CAP / 4).fill(false);
140	  constructor() { this.group.name = 'drive-wheels'; this.group.visible = false; }
141	  /* Dựng 3 InstancedMesh từ lưới bánh của nguồn (một lần cho mỗi nguồn) */
142	  setup(src: DrSource): void {
143	    if (this.src === src) return;
144	    this.reset();
145	    this.src = src;
146	    for (const m of src.wheelMeshes) {
147	      const im = new THREE.InstancedMesh(m.geometry, m.material, CAP);
148	      im.name = 'drive-wheels-' + (Array.isArray(m.material) ? '' : m.material.name);
149	      im.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
150	      for (let i = 0; i < CAP; i++) im.setMatrixAt(i, ZERO);
151	      im.count = 0; im.frustumCulled = false; im.castShadow = false; im.receiveShadow = false; im.layers.set(1);
152	      this.meshes.push(im); this.group.add(im);
153	    }
154	  }
155	  /* Chỗ trống đầu tiên (chỉ số instance đầu của 4 bánh), -1 nếu hết */
156	  acquire(): number {
157	    const k = this.used.indexOf(false);
158	    if (k < 0) return -1;
159	    this.used[k] = true;
160	    this.group.visible = true;
161	    this.fit();
162	    return k * 4;
163	  }
164	  release(base: number): void {
165	    if (base < 0) return;
166	    this.used[base / 4] = false;
167	    for (const im of this.meshes) { for (let i = 0; i < 4; i++) im.setMatrixAt(base + i, ZERO); im.instanceMatrix.needsUpdate = true; }
168	    this.fit();
169	  }
170	  private fit(): void {
171	    const top = this.used.lastIndexOf(true);
172	    for (const im of this.meshes) im.count = (top + 1) * 4;
173	    this.group.visible = top >= 0;
174	  }
175	  /* Ma trận 4 bánh của xe có ma trận thế giới `car` */
176	  set(base: number, car: THREE.Matrix4, steer: number, wheel: number): void {
177	    const w = this.src!.wheels;
178	    for (let i = 0; i < 4; i++) {
179	      const d = w[i];
180	      Q.setFromAxisAngle(AXY, i < 2 ? steer : 0).multiply(d.quat).multiply(Q2.setFromAxisAngle(AXZ, d.sign * wheel));   // lái (chỉ bánh trước), xoay nghỉ của nút, rồi lăn quanh Z cục bộ
181	      A.compose(d.pos, Q, UNIT);
182	      B.multiplyMatrices(car, A);
183	      for (const im of this.meshes) im.setMatrixAt(base + i, B);
184	    }
185	    for (const im of this.meshes) im.instanceMatrix.needsUpdate = true;
186	  }
187	  reset(): void {
188	    for (const im of this.meshes) { this.group.remove(im); im.dispose(); }
189	    this.meshes = []; this.src = null; this.used.fill(false); this.group.visible = false;
190	  }
191	}
192	const B3 = new THREE.Quaternion();
193	export const drWheels = new DrWheelPool();
194	
195	/* ===== Hình tạm và tấm bóng dùng chung ===== */
196	let tempMat: THREE.MeshStandardMaterial | null = null, shadowMat: THREE.MeshBasicMaterial | null = null, shadowGeo: THREE.PlaneGeometry | null = null, shadowTex: THREE.DataTexture | null = null;
197	
198	function drTempGeometry(color: string): THREE.BufferGeometry {
199	  const L = CAR.length, W = CAR.width, H = CAR.height - CAR.clearance, r = CAR.wheelDia / 2, ww = M.temp.wheelWidth;
200	  const col = new THREE.Color(color), dark = new THREE.Color(0x15151a);
201	  const paint = (g: THREE.BufferGeometry, c: THREE.Color): THREE.BufferGeometry => {
202	    const n = g.attributes.position.count, a = new Float32Array(n * 3);
203	    for (let i = 0; i < n; i++) { a[i * 3] = c.r; a[i * 3 + 1] = c.g; a[i * 3 + 2] = c.b; }
204	    g.setAttribute('color', new THREE.BufferAttribute(a, 3));
205	    return g;
206	  };
207	  const parts: THREE.BufferGeometry[] = [paint(new RoundedBoxGeometry(L, H, W, 2, 0.12).translate(0, CAR.clearance + H / 2, 0), col)];
208	  const ax = CAR.wheelbase / 2, az = W / 2 - ww / 2;
209	  for (const sx of [1, -1]) for (const sz of [1, -1]) {
210	    parts.push(paint(new THREE.CylinderGeometry(r, r, ww, 12).rotateX(Math.PI / 2).translate(sx * ax, r, sz * az), dark));
211	  }
212	  const g = mergeGeometries(parts.map((p) => p.index ? p.toNonIndexed() : p))!;   // 1 Mesh gộp
213	  for (const p of parts) p.dispose();
214	  return g;
215	}
216	
217	function drShadowShared(): void {
218	  if (shadowMat) return;
219	  const n = 32, d = new Uint8Array(n * n * 4);
220	  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
221	    const u = (x + 0.5) / n * 2 - 1, v = (y + 0.5) / n * 2 - 1;
222	    const e = Math.max(Math.abs(u), Math.abs(v)), a = e >= 1 ? 0 : 1 - e * e * e * e;   // mép mềm hình vuông bo
223	    d[(y * n + x) * 4 + 3] = Math.round(255 * a);
224	  }
225	  shadowTex = new THREE.DataTexture(d, n, n, THREE.RGBAFormat); shadowTex.needsUpdate = true;
226	  shadowTex.magFilter = shadowTex.minFilter = THREE.LinearFilter;
227	  shadowMat = new THREE.MeshBasicMaterial({ color: 0x000000, map: shadowTex, transparent: true, opacity: M.shadow.opacity, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2, fog: false });
228	  shadowMat.name = 'driveShadow';
229	  shadowGeo = new THREE.PlaneGeometry(1, 1).rotateX(-Math.PI / 2);
230	}
231	function drTempMaterial(): THREE.MeshStandardMaterial {
232	  if (!tempMat) { tempMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.6, metalness: 0.1 }); tempMat.name = 'driveTemp'; }
233	  return tempMat;
234	}
235	/* Giải phóng vật liệu / bánh dùng chung (rời chế độ hẳn) */
236	export function drCarDisposeShared(): void {
237	  drWheels.reset();
238	  tempMat?.dispose(); tempMat = null;
239	  shadowMat?.dispose(); shadowGeo?.dispose(); shadowTex?.dispose(); shadowMat = null; shadowGeo = null; shadowTex = null;
240	}
241	
242	/* ===== Một xe ===== */
243	export class DrCar {
244	  readonly group = new THREE.Group();
245	  private readonly color: string;
246	  private temp: THREE.Mesh | null;
247	  private tempGeo: THREE.BufferGeometry | null;
248	  private shadow: THREE.Mesh;
249	  private body: THREE.Object3D | null = null;
250	  private paint: THREE.MeshStandardMaterial | null = null;
251	  private tailMeshes: THREE.Mesh[] = [];
252	  private src: DrSource | null = null;
253	  private slot = -1;
254	  private disposed = false;
255	  private brakingNow = false;
256	  private last: DrPlace | null = null;
257	
258	  constructor(color: string) {
259	    this.color = color;
260	    this.group.name = 'drive-car';
261	    this.group.matrixAutoUpdate = true;
262	    this.tempGeo = drTempGeometry(color);
263	    this.temp = new THREE.Mesh(this.tempGeo, drTempMaterial());
264	    this.temp.layers.set(1); this.temp.castShadow = false; this.temp.receiveShadow = false;
265	    this.group.add(this.temp);
266	    drShadowShared();
267	    this.shadow = new THREE.Mesh(shadowGeo!, shadowMat!);
268	    this.shadow.scale.set(CAR.length + 2 * M.shadow.pad, 1, CAR.width + 2 * M.shadow.pad);
269	    this.shadow.position.y = M.shadow.lift;
270	    this.shadow.layers.set(1); this.shadow.castShadow = false; this.shadow.receiveShadow = false; this.shadow.renderOrder = 1;
271	    this.group.add(this.shadow);
272	    drCarLoad().then((scene) => { if (scene && !this.disposed) this.swap(sources.get(scene)!); }, () => { /* drCarLoad không từ chối */ });
273	  }
274	
275	  get real(): boolean { return this.body !== null; }
276	
277	  /* Đổi hình tạm sang bản sao mô hình thật, giữ nguyên vị trí */
278	  private swap(src: DrSource): void {
279	    if (this.body) return;
280	    drWheels.setup(src);
281	    this.slot = drWheels.acquire();
282	    this.src = src;
283	    const body = src.body.clone();
284	    this.paint = src.paint.clone();
285	    this.paint.color.set(this.color); this.paint.roughness = M.paintRough; this.paint.metalness = M.paintMetal;
286	    body.traverse((o) => {
287	      const m = o as THREE.Mesh;
288	      if (!m.isMesh) return;
289	      const mat = m.material as THREE.Material;
290	      if (mat.name === 'paint') m.material = this.paint!;
291	      else if (mat === src.tail) this.tailMeshes.push(m);
292	    });
293	    this.body = body;
294	    this.group.add(body);
295	    if (this.temp) { this.group.remove(this.temp); this.temp = null; this.tempGeo!.dispose(); this.tempGeo = null; }
296	    this.brakingNow = false;
297	    if (this.last) this.place(this.last);
298	  }
299	
300	  place(p: DrPlace): void {
301	    const l = this.last || (this.last = { x: 0, y: 0, z: 0, yaw: 0, pitch: 0, steer: 0, wheel: 0, braking: false });
302	    l.x = p.x; l.y = p.y; l.z = p.z; l.yaw = p.yaw; l.pitch = p.pitch; l.steer = p.steer; l.wheel = p.wheel; l.braking = p.braking;
303	    const g = this.group;
304	    g.position.set(p.x, p.y, p.z);
305	    g.quaternion.setFromAxisAngle(AXY, p.yaw).multiply(B3.setFromAxisAngle(AXZ, p.pitch));
306	    if (!this.body) return;
307	    if (p.braking !== this.brakingNow) {
308	      this.brakingNow = p.braking;
309	      const mat = p.braking ? this.src!.tailBrake : this.src!.tail;
310	      for (const m of this.tailMeshes) m.material = mat;
311	    }
312	    if (this.slot >= 0) { g.updateMatrix(); drWheels.set(this.slot, g.matrix, p.steer, p.wheel); }
313	  }
314	
315	  dispose(): void {
316	    if (this.disposed) return;
317	    this.disposed = true;
318	    this.group.removeFromParent();
319	    drWheels.release(this.slot); this.slot = -1;
320	    this.tempGeo?.dispose(); this.tempGeo = null;
321	    this.paint?.dispose(); this.paint = null;
322	    this.body = null; this.temp = null; this.tailMeshes.length = 0;
323	  }
324	}
325	
