1	/* ============================ Đi dạo: đầu vào từ bàn phím (thuần) ============================
2	   W/↑ tới, S/↓ lùi, A/← trái, D/→ phải theo hướng camera; chéo chuẩn hóa về độ dài 1; Shift chạy. Space không điều khiển gì (đã bỏ nhảy, D-030); index.ts chỉ chặn hành vi mặc định của nó.
3	   Không cấp phát (gọi mỗi khung). */
4	import type { StInput } from './motion';
5	
6	/* Tên phím chuẩn theo vị trí vật lý (e.code) để bố cục không Latin (ru, ar, th, hi) vẫn dùng được WASD / P / Shift / Space; không có code thì dùng e.key. Chỉ đi dạo dùng, phím dù lượn giữ nguyên. */
7	const ST_CODE_KEY: Record<string, string> = { KeyW: 'w', KeyA: 'a', KeyS: 's', KeyD: 'd', KeyP: 'p', ShiftLeft: 'shift', ShiftRight: 'shift', Space: ' ' };
8	export function stKeyName(e: { key: string; code?: string }): string {
9	  return (e.code && ST_CODE_KEY[e.code]) || e.key.toLowerCase();
10	}
11	
12	export function stInputFromKeys(keys: Set<string>, camYaw: number, out: StInput): StInput {
13	  let f = 0, r = 0;
14	  if (keys.has('w') || keys.has('arrowup')) f += 1;
15	  if (keys.has('s') || keys.has('arrowdown')) f -= 1;
16	  if (keys.has('d') || keys.has('arrowright')) r += 1;
17	  if (keys.has('a') || keys.has('arrowleft')) r -= 1;
18	  const len = Math.sqrt(f * f + r * r);
19	  if (len > 1) { f /= len; r /= len; }
20	  out.mz = f; out.mx = r; out.run = keys.has('shift'); out.camYaw = camYaw;
21	  return out;
22	}
