// Lái thử Task 7 (không phải test của dự án): đọc dist/, SwiftShader. node drive-try.mjs
import { serveDir, launch, openApp, frames } from 'file:///D:/2026%20-%20Tuan/danang-vite/tests/lib.mjs';
import { mkdirSync } from 'node:fs';

const ROOT = 'D:/2026 - Tuan/danang-vite';
const SHOTS = ROOT + '/tests/screens/';
mkdirSync(SHOTS, { recursive: true });
const t0 = Date.now();
const log = (...a) => console.log(`[${((Date.now() - t0) / 1000).toFixed(0)}s]`, ...a);

const srv = await serveDir(ROOT + '/dist');
const browser = await launch();
let release; const gate = new Promise((r) => { release = r; });
const warns = [];
const { page, errors } = await openApp(browser, srv.url + '?explore=drive', { width: 800, height: 450, before: async (p) => {
  p.on('console', (m) => { if (m.type() === 'warning' || /\[drive\]/.test(m.text())) warns.push(m.text()); });
  await p.route('**/car/vf3.glb', async (r) => { await gate; await r.continue(); });
} });
log('mở xong');
const info = await page.evaluate(() => {
  const a = window.__app, d = a.drive;
  return { mode: a.cam.mode, body: document.body.className, stats: { ...d.stats }, pads: d.net.pads.length, solids: d.net.solids.length,
    s: { x: d.state.x, y: d.state.y, z: d.state.z, yaw: d.state.yaw }, cam: a.camera.position.toArray().map((v) => +v.toFixed(2)), fov: a.camera.fov };
});
log('vào chế độ', JSON.stringify(info));
await frames(page, 3);
const real = () => page.evaluate(() => !!window.__app.scene.getObjectByName('drive-cars')?.getObjectByName('body'));
const progs = () => page.evaluate(() => window.__app.renderer.info.programs.length);
const calls = () => page.evaluate(() => window.__app.renderer.info.render.calls);
const P0 = await progs(), R0 = await real();
log('hình tạm: programs', P0, 'real', R0, 'calls', await calls());
release();
await page.waitForFunction(() => !!window.__app.scene.getObjectByName('drive-cars')?.getObjectByName('body'), null, { timeout: 120000, polling: 200 });
const P1a = await progs();
await frames(page, 3);
const P1 = await progs();
log('mô hình thật hiện: programs ngay khi đổi', P1a, 'sau 3 khung', P1, 'calls', await calls());
/* lái 5 s thật bằng phím */
await page.keyboard.down('KeyW'); await page.waitForTimeout(2500);
await page.keyboard.down('KeyA'); await page.waitForTimeout(1000); await page.keyboard.up('KeyA');
await page.keyboard.up('KeyW'); await page.keyboard.down('KeyS'); await page.waitForTimeout(1500); await page.keyboard.up('KeyS');
await frames(page, 2);
const P2 = await progs();
const afterKeys = await page.evaluate(() => { const s = window.__app.drive.state; return { x: +s.x.toFixed(2), z: +s.z.toFixed(2), yaw: +s.yaw.toFixed(3), v: +s.v.toFixed(2) }; });
log('sau 5 s lái bằng phím: programs', P2, JSON.stringify(afterKeys));

/* ===== Chạy bằng số (mô phỏng trong một lần evaluate, không có khung xen giữa) ===== */
const sim = (args) => page.evaluate(({ x, z, yaw, inp, T, until }) => {
  const d = window.__app.drive; d.placeAt(x, z, yaw);
  const s = () => d.state; let t = 0, yMin = Infinity, yMax = -Infinity, zMin = Infinity, zMax = -Infinity, stuck = 0, xMax = -Infinity, xMin = Infinity;
  const dt = 1 / 60;
  while (t < T) {
    d.step(dt, inp); t += dt;
    const st = s();
    yMin = Math.min(yMin, st.y); yMax = Math.max(yMax, st.y); zMin = Math.min(zMin, st.z); zMax = Math.max(zMax, st.z); xMax = Math.max(xMax, st.x); xMin = Math.min(xMin, st.x);
    if (t > 3 && Math.abs(st.v) < 0.5) stuck += dt;
    if (until && until(st)) break;
  }
  const st = s();
  return { t: +t.toFixed(2), x: +st.x.toFixed(2), y: +st.y.toFixed(2), z: +st.z.toFixed(2), yaw: +st.yaw.toFixed(3), v: +st.v.toFixed(2), kmh: +(st.v * 3.6).toFixed(1),
    yMin: +yMin.toFixed(2), yMax: +yMax.toFixed(2), zMin: +zMin.toFixed(2), zMax: +zMax.toFixed(2), xMin: +xMin.toFixed(1), xMax: +xMax.toFixed(1), stuck: +stuck.toFixed(2) };
}, args);
const GAS = { gas: 1, brake: 0, steer: 0, hand: false };
const runs = {};
runs.ga6s = await sim({ x: -150, z: 8.625, yaw: 0, inp: GAS, T: 6 });
const pass = (lim) => new Function('s', `return s.x > ${lim}`);
// until không qua được structured clone: dùng T đủ dài thay vì until
runs.dragon = await sim({ x: -600, z: 8.625, yaw: 0, inp: GAS, T: 60 });
runs.railStraight = await sim({ x: -100, z: 8.625, yaw: -Math.PI / 2, inp: GAS, T: 5 });
runs.railOblique = await sim({ x: -100, z: 8.625, yaw: -0.3, inp: GAS, T: 6 });
runs.tunnelS = await sim({ x: -800, z: -1700 + 8.35, yaw: 0, inp: GAS, T: 75 });
runs.tunnelN = await sim({ x: 800, z: -1700 - 8.35, yaw: Math.PI, inp: GAS, T: 75 });
runs.songHan = await sim({ x: -600, z: -1080 + 2.8, yaw: 0, inp: GAS, T: 60 });
runs.ttl = await sim({ x: -750, z: 1300 + 8.4, yaw: 0, inp: GAS, T: 75 });
runs.tp = await sim({ x: -1300, z: -2900 + 4, yaw: 0, inp: GAS, T: 120 });
runs.westN = await sim({ x: -1064 + 6, z: 1200, yaw: Math.PI / 2, inp: GAS, T: 200 });
void pass;
for (const [k, v] of Object.entries(runs)) log('sim', k, JSON.stringify(v));

/* bánh lăn đúng chiều: điểm đỉnh lốp trước trái tiến theo hướng xe khi xe tiến */
const roll = await page.evaluate(() => {
  const a = window.__app, d = a.drive, T = a.THREE;
  d.placeAt(-150, 8.625, 0);
  const im = a.scene.getObjectByName('drive-wheels').children[0];
  const M1 = new T.Matrix4(), M2 = new T.Matrix4();
  d.step(1 / 60, { gas: 0, brake: 0, steer: 0, hand: false });
  im.getMatrixAt(0, M1);
  const pts = []; for (let i = 0; i < 16; i++) { const th = i / 16 * Math.PI * 2; pts.push(new T.Vector3(0.33 * Math.cos(th), 0.33 * Math.sin(th), 0)); }
  const w1 = pts.map((p) => p.clone().applyMatrix4(M1));
  const top = w1.reduce((b, p, i) => (p.y > w1[b].y ? i : b), 0);
  const c1 = new T.Vector3().applyMatrix4(M1);
  d.state.v = 2; d.step(0.05, { gas: 0.2, brake: 0, steer: 0, hand: false });
  im.getMatrixAt(0, M2);
  const c2 = new T.Vector3().applyMatrix4(M2), p2 = pts[top].clone().applyMatrix4(M2);
  return { centerDx: +(c2.x - c1.x).toFixed(3), topDx: +(p2.x - w1[top].x).toFixed(3), name: im.name, count: im.count };
});
log('bánh lăn', JSON.stringify(roll), roll.topDx > roll.centerDx ? 'đỉnh lốp đi nhanh hơn tâm: lăn đúng chiều' : 'SAI CHIỀU?');

/* ===== Ảnh ===== */
const shots = [
  ['drive-dragon', -120, 8.625, 0], ['drive-songhan', -200, -1080 + 2.8, 0], ['drive-ttl', -250, 1300 + 8.4, 0],
  ['drive-thuanphuoc', -400, -2900 + 4, 0], ['drive-tunnel', -100, -1700 + 8.35, 0], ['drive-west', -1064 + 6, -1650, Math.PI / 2]
];
for (const [name, x, z, yaw] of shots) {
  await page.evaluate(([x, z, yaw]) => window.__app.drive.placeAt(x, z, yaw), [x, z, yaw]);
  await frames(page, 4);
  const c = await page.evaluate(() => { const a = window.__app, s = a.drive.state; return { cam: a.camera.position.toArray().map((v) => +v.toFixed(2)), car: [+s.x.toFixed(2), +s.y.toFixed(2), +s.z.toFixed(2)], calls: a.renderer.info.render.calls, hrInside: a.hr?.inside ?? null }; });
  await page.screenshot({ path: SHOTS + name + '.png' });
  log('ảnh', name, JSON.stringify(c));
}
/* bẻ lái để thấy bánh trước */
await page.evaluate(() => window.__app.drive.placeAt(-120, 8.625, 0));
await page.evaluate(() => { const c = window.__app.drive.cam; c.yaw = 2.4; c.pitch = 0.25; c.idle = -100; });
await page.keyboard.down('KeyA'); await frames(page, 4); await page.screenshot({ path: SHOTS + 'drive-steer.png' }); await page.keyboard.up('KeyA');
log('ảnh drive-steer');
/* ban đêm */
await page.evaluate(() => { window.__app.dayNight.target = 1; window.__app.dayNight.night = 1; window.__app.drive.placeAt(-120, 8.625, 0); const c = window.__app.drive.cam; c.yaw = 2.6; c.pitch = 0.15; c.idle = -100; });
await frames(page, 4); await page.screenshot({ path: SHOTS + 'drive-night-front.png' });
await page.evaluate(() => { const c = window.__app.drive.cam; c.yaw = 0; c.pitch = 0; c.idle = 0; });
await page.keyboard.down('KeyS'); await frames(page, 4); await page.screenshot({ path: SHOTS + 'drive-night-brake.png' }); await page.keyboard.up('KeyS');
const P3 = await progs();
log('ảnh đêm; programs', P3);
log('cảnh báo', JSON.stringify(warns));
log('lỗi', JSON.stringify(errors));
log('TÓM TẮT programs', JSON.stringify({ P0, P1a, P1, P2, P3 }));
await browser.close(); srv.close();

