// Dò hai điểm lạ trong ảnh lái thử: vạch đen ngang ở Trần Thị Lý, mảng xanh sau kính hậu ban đêm
import { serveDir, launch, openApp, frames } from 'file:///D:/2026%20-%20Tuan/danang-vite/tests/lib.mjs';
const ROOT = 'D:/2026 - Tuan/danang-vite', SHOTS = ROOT + '/tests/screens/';
const srv = await serveDir(ROOT + '/dist');
const browser = await launch();
const { page, errors } = await openApp(browser, srv.url + '?explore=drive', { width: 800, height: 450 });
await page.waitForFunction(() => !!window.__app.scene.getObjectByName('drive-cars')?.getObjectByName('body'), null, { timeout: 120000, polling: 200 });
await page.evaluate(() => window.__app.drive.placeAt(-250, 1308.4, 0));
await frames(page, 3);
const hit = await page.evaluate(() => {
  const a = window.__app, T = a.THREE, rc = new T.Raycaster(); rc.layers.enableAll();
  const out = [];
  for (const y of [-0.28, -0.30, -0.31, -0.32, -0.34]) for (const x of [-0.6, 0.55]) {
    rc.setFromCamera({ x, y }, a.camera);
    const h = rc.intersectObjects(a.scene.children, true).filter((i) => i.object.visible)[0];
    if (h) { let n = h.object, path = []; while (n && path.length < 4) { path.push(n.name || n.type); n = n.parent; } out.push({ x, y, d: +h.distance.toFixed(2), p: h.point.toArray().map((v) => +v.toFixed(2)), path, mat: h.object.material?.name || h.object.material?.type }); }
  }
  return out;
});
console.log('TTL tia:', JSON.stringify(hit, null, 0));
await page.screenshot({ path: SHOTS + 'drive-ttl-probe.png' });
/* đêm: nhìn sau xe, có / không đèn pha; rồi phanh khi đang chạy */
await page.evaluate(() => { window.__app.dayNight.target = 1; window.__app.dayNight.night = 1; window.__app.drive.placeAt(-120, 8.625, 0); });
await frames(page, 3); await page.screenshot({ path: SHOTS + 'drive-night-rear.png' });
const names = await page.evaluate(() => { const r = []; window.__app.scene.getObjectByName('drive-cars').traverse((o) => { if (o.isMesh) r.push([o.material.name, o.material.side, o.material.transparent]); }); return r; });
console.log('lưới xe:', JSON.stringify(names));
await page.evaluate(() => window.__app.scene.getObjectByName('drive-cars').traverse((o) => { if (o.isMesh && o.material.name === 'lamp_head') o.visible = false; }));
await frames(page, 3); await page.screenshot({ path: SHOTS + 'drive-night-rear-nohead.png' });
await page.evaluate(() => window.__app.scene.getObjectByName('drive-cars').traverse((o) => { if (o.isMesh && o.material.name === 'lamp_head') o.visible = true; }));
await page.evaluate(() => { const d = window.__app.drive; d.state.v = 12; });
await page.keyboard.down('KeyS'); await frames(page, 2);
const br = await page.evaluate(() => window.__app.drive.state.braking);
await page.screenshot({ path: SHOTS + 'drive-night-brake.png' }); await page.keyboard.up('KeyS');
console.log('đang phanh:', br, 'lỗi', JSON.stringify(errors));
await browser.close(); srv.close();

